 scenes:[
  {t:'Види внутрішніх посилань', app:'Сайт', url:'site.ua/blog/yak-vybraty-velosyped/', rows:['~ Меню: Велосипеди · Аксесуари · Ремонт','~ Хлібні крихти: Головна › Блог › Як вибрати велосипед','Для поїздок містом підійде [міський велосипед] з кошиком...','# Схожі статті: Як доглядати за ланцюгом · Розмір рами','~ Футер: Доставка · Оплата · Контакти'], hl:2, say:'Посилання бувають навігаційні: меню, крихти, футер, і контекстні: прямо в тексті. Контекстні найцінніші, бо оточені змістом і мають описовий анкор. Тут стаття веде на категорію міських велосипедів.'},
  {t:'Анкор', app:'Порівняння', url:'текст посилання', rows:['+ Дивіться наш каталог [міських велосипедів]','+ [Як вибрати розмір рами] за зростом','! Детальніше [тут]','! [Натисніть сюди], щоб перейти','! [https://site.ua/velosypedy/miski/]'], hl:0, say:'Анкор це текст посилання. Він підказує Google, про що цільова сторінка. «Міських велосипедів» чудовий анкор. «Тут» або «натисніть сюди» нічого не пояснюють. Анкори варто різноманітити, але завжди за змістом.'},
  {t:'Inlinks у Screaming Frog', app:'Screaming Frog', url:'Internal → /velosypedy/miski/', side:['Internal'], sel:0, rows:['|! Address | Inlinks | Unique Inlinks | Crawl Depth','| /velosypedy/ | 412 | 410 | 1','| /velosypedy/miski/ | 6 | 4 | 3','| /velosypedy/elektro/ | 1 | 1 | 5','? Важлива категорія «електро» має 1 посилання і глибину 5: треба посилити'], hl:3, say:'У Screaming Frog колонки Inlinks, Unique Inlinks і Crawl Depth показують, скільки внутрішніх посилань веде на сторінку і на якій вона глибині. Важливі сторінки з малою кількістю посилань і великою глибиною треба посилювати.'},
  {t:'Сироти', app:'Screaming Frog', url:'Sitemaps → Orphan URLs', side:['Sitemaps'], sel:0, rows:['= Configuration → API Access → Google Search Console (Connect)','[Crawl Analysis]','|! Orphan URL | Джерело','| /akciya-litnya/ | Sitemap','| /blog/stara-statya/ | GSC','~ Сторінки є в sitemap/GSC, але на сайті на них не веде жодне посилання'], hl:4, say:'Сирота це сторінка, на яку не веде жодне внутрішнє посилання. Робот знаходить її хіба що через sitemap. Підключіть Search Console в API Access, запустіть Crawl Analysis і подивіться Orphan URLs.'},
  {t:'Знаходимо, звідки поставити посилання', app:'Google', url:'google.com/search?q=site:site.ua+"міський велосипед"', rows:['= site:site.ua "міський велосипед"','| /blog/yak-vybraty-velosyped/ | згадує «міський велосипед»','| /blog/velosyped-na-robotu/ | згадує «міський велосипед»','+ Ставимо з цих статей посилання на /velosypedy/miski/'], hl:0, say:'Простий прийом: шукаємо в Google site двокрапка ваш домен і ключову фразу в лапках. Google покаже ваші сторінки, де вона згадується. З них і ставимо контекстні посилання на цільову сторінку.'}
 ],
